    await expect(pg_vic.getByTestId("rollup-due-total")).toHaveText("3.33");
    await expect(pg_vic.getByTestId("rollup-overdue-count")).toHaveText("1");
    await expect(pg_vic.getByTestId("rollup-overdue-total")).toHaveText("1.13");
    await ui.expectAudit(sheet, [
      `RATE_SET sheet=${sheet} by=uma grade=A rate=10.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=terms value=5`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=late-pct value=10.00`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=20.00 date=2026-02-01`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=10.25 date=2026-01-01`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=20.00 date=2026-02-01 number=1`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=20.00 due-total=2.00 overdue-total=2.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=20.00 due-total=2.00 overdue-total=2.00`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=10.25 date=2026-01-01 number=2`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=30.25 due-total=3.03 overdue-total=3.03`,
      `TOTALS sheet=${sheet} by=uma claimed-total=30.25 due-total=3.03 overdue-total=3.03`,
      `STATEMENT sheet=${sheet} by=uma name=Ada due-total=3.03 claims=2`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=late-pct value=20.00 from=2026-03-01`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=30.25 due-total=3.33 overdue-total=3.33`,
      `TOTALS sheet=${sheet} by=uma claimed-total=30.25 due-total=3.33 overdue-total=3.33`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=late-pct value=0.00 from=2026-04-01`,
      `CLAIM_SETTLED sheet=${sheet} by=vic person=Ada amount=20.00 date=2026-02-01 number=1 due=2.20`,
      `ROLLUP sheet=${sheet} by=vic person=Ada claimed=30.25 due-total=3.33 overdue-total=1.13`,
      `TOTALS sheet=${sheet} by=vic claimed-total=30.25 due-total=3.33 overdue-total=1.13`
    ]);
  });
  test("late per boundary scenario 1", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
